#ifndef SIGPIPE_SAFE_WRITE_H
#define SIGPIPE_SAFE_WRITE_H

#include <cerrno>
#include <csignal>
#include <cstddef>
#include <ctime>
#include <pthread.h>
#include <unistd.h>

/* Write without changing the process-wide SIGPIPE disposition. SIGPIPE is
 * blocked only on the calling thread. A signal that was already pending is
 * left pending; after EPIPE, only a signal generated by this write is consumed
 * with a zero-timeout wait. EINTR from write is retried. */
static inline ssize_t sigpipe_safe_write(int fd, const void *buffer, size_t size) {
    sigset_t sigpipe_set;
    sigemptyset(&sigpipe_set);
    sigaddset(&sigpipe_set, SIGPIPE);

    sigset_t old_mask;
    int mask_error = pthread_sigmask(SIG_BLOCK, &sigpipe_set, &old_mask);
    if (mask_error != 0) {
        errno = mask_error;
        return -1;
    }

    sigset_t pending;
    if (sigpending(&pending) != 0) {
        int pending_error = errno;
        int restore_error = pthread_sigmask(SIG_SETMASK, &old_mask, nullptr);
        errno = restore_error != 0 ? restore_error : pending_error;
        return -1;
    }
    bool was_pending = sigismember(&pending, SIGPIPE) == 1;

    ssize_t result;
    do {
        result = write(fd, buffer, size);
    } while (result < 0 && errno == EINTR);
    int write_error = errno;

    if (result < 0 && write_error == EPIPE && !was_pending) {
#if defined(__linux__)
        struct timespec timeout {};
        while (sigtimedwait(&sigpipe_set, nullptr, &timeout) < 0 &&
               errno == EINTR) {
        }
#else
        /* Darwin has no sigtimedwait. A pipe-generated SIGPIPE is directed to
        * this blocked thread, so consume it only after sigpending proves it
        * exists; sigwait then cannot wait for an unrelated process signal. */
        sigset_t after_write;
        if (sigpending(&after_write) == 0 &&
            sigismember(&after_write, SIGPIPE) == 1) {
            int consumed_signal = 0;
            (void)sigwait(&sigpipe_set, &consumed_signal);
        }
#endif
    }

    int restore_error = pthread_sigmask(SIG_SETMASK, &old_mask, nullptr);
    if (restore_error != 0) {
        errno = restore_error;
        return -1;
    }
    errno = write_error;
    return result;
}

#endif /* SIGPIPE_SAFE_WRITE_H */
